const track0 = {
  color: '#e09f3e',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["y = \\Rev\\Big[a(\\tau)\\sum_{k} A_k\\sin\\big(2\\pi k\\!\\int\\! f\\,dt + \\varphi_k\\big)\\Big],\\quad A_k = \\frac{B(kf)}{k^{p}}\\ \\text{— гармоники по спектру инструмента: наклон источника и резонансы корпуса}","f = f_0\\,2^{(v(\\tau)\\sin 2\\pi f_v t - s\\,e^{-\\tau/45\\text{мс}})/1200}\\ \\text{— вибрато приходит позже, подъезд к ноте, легато — глиссандо}"],
  audio({ bpm }) {
    const sec = 60 / bpm, a = soloist('sax', { vib: 1, glide: 0.05, scoop: 28, accent: 0.2, seed: 5 }), verb = hall({ size: 0.72, decay: 1.3, damp: 4500, wet: 0.26 })
    let n = 0, vel = 0.8
    return x => {
      const m = leadAt(x)
      if (m) { n = m.n; vel = 0.6 + 0.07 * Math.max(0, energy(x)) + 0.16 * hash(floor(2 * m.at), 5) + (mod(m.at, 4) === 0 ? 0.06 : 0) }
      const on = !!m && m.u < 0.94, f = hz(n + 0, C4)
      const y = 2.3 * (a(f, on, vel))
      return verb(...pan(y, 0.12))
    }
  },
}

// ---- vibes2 ------------------------------------------------------------------------------------
const track1 = {
  color: '#b8f0ff',
  graph: x => { const m = lead2At(x); return m ? 1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = lead2At(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["P = \\Rev\\sum_{k}\\big(0.72\\,e^{-t/\\tau_k} + 0.28\\,e^{-t/5\\tau_k}\\big)A_k(v)\\sin 2\\pi f_k t,\\quad f_k = kf\\sqrt{1 + Bk^2}\\ \\text{— струна с жёсткостью, быстрый звук и послезвучие}","A_k(v) = \\frac{|\\sin(0.123\\pi k)|^{0.6}}{k^{\\,0.75 + 1.1(1 - v)}}\\cdot\\frac{1}{1 + (f_k/f_c(v))^2}\\ \\text{— удар на ⅛ струны, войлок твёрже при сильном ударе}"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = polyWide(vibesTone, { release: 0.5, life: 5, width: 0.4 }), fire = trigger(), verb = hall({ size: 0.72, decay: 1.3, damp: 4500, wet: 0.26 })
    return x => {
      const m = lead2At(x)
      if (fire(m ? m.at : null)) {
        const v = 0.62 + 0.08 * Math.max(0, energy(x)) + 0.14 * hash(floor(4 * m.at), 3) + (mod(m.at, 4) === 0 ? 0.06 : 0)
        p.hit(hz(m.n + 0, C4), v, m.d * sec + 0.5)
      }
      const [l, r] = p(), k = 0.4455
      return verb(...[k * l, k * r].map((s, i) => s * (i ? 0.7 : 1.3)))
    }
  },
}

